import torch


def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    dtype = getattr(torch, ctx["x__dtype"])
    # lgamma requires positive values: torch.rand(shape) + 0.1
    x = torch.rand(shape, dtype=dtype, device=device) + 0.1
    return {"x": x}


def run(x):
    return x.lgamma()
